import React from 'react';
import { ResizableBox } from 'react-resizable';
import 'react-resizable/css/styles.css';
import Avatar from './Avatar';

const SplitScreen = ({ avatarProps, rightContent, isLeftCollapsed, setIsLeftCollapsed, leftWidth, setLeftWidth }) => {
  return (
    <div className="flex h-screen bg-gradient-to-br from-black via-gray-900 to-purple-900">
      <ResizableBox
        width={isLeftCollapsed ? 50 : leftWidth}
        height={window.innerHeight}
        axis="x"
        minConstraints={[50, 100]}
        maxConstraints={[window.innerWidth - 50, window.innerHeight]}
        onResize={(e, data) => setLeftWidth(data.size.width)}
        className="p-4 border-r"
      >
        <button
          onClick={() => setIsLeftCollapsed(!isLeftCollapsed)}
          className="absolute top-2 right-2 bg-gray-500 text-white px-2 py-1 rounded"
        >
          {isLeftCollapsed ? '➕' : '➖'}
        </button>
        {!isLeftCollapsed && <Avatar {...avatarProps} />}
      </ResizableBox>
      <div className="flex-1 p-4 overflow-auto">{rightContent}</div>
    </div>
  );
};

export default SplitScreen;