import React, { useEffect, useState, useRef } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { FaSpinner } from 'react-icons/fa';
import SplitScreen from './common/SplitScreen';
import NavBar from "../NavBar.jsx";
import Avatar from './Avatar';

const CodeEditorPage = () => {
  const navigate = useNavigate();
  const { state } = useLocation();
  const { selectedTech, resumeData } = state || {};
  const userName = resumeData?.name || 'User';
  const userGender = localStorage.getItem('userGender') || 'male';
  const [avatarState, setAvatarState] = useState('observing');
  const [avatarMessage, setAvatarMessage] = useState('');
  const [avatarExpression, setAvatarExpression] = useState('entry');
  const [isLeftCollapsed, setIsLeftCollapsed] = useState(false);
  const [leftWidth, setLeftWidth] = useState(window.innerWidth / 2);
  const [rightContent, setRightContent] = useState('Welcome to MockInterview');
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(-1);
  const [timer, setTimer] = useState(0);
  const [warnings, setWarnings] = useState([]);
  const [scores, setScores] = useState({ resume: 0, introduction: 0, nonTechnical: 0, technical: 0 });
  const [microAchievements, setMicroAchievements] = useState([]);
  const [isRecording, setIsRecording] = useState(false);
  const [showConsentModal, setShowConsentModal] = useState(true);
  const timerRef = useRef(null);
  const mediaRecorderRef = useRef(null);
  const recordedChunks = useRef([]);

  // Mock resume parsing
  const resume = {
    hobbies: resumeData?.hobbies || ['reading', 'music'],
    skills: resumeData?.skills || ['JavaScript', 'React'],
    projects: resumeData?.projects || ['Built a React app'],
  };

  // Track-specific question banks
  const questionBanks = {
    Frontend: [
      { type: 'introduction', text: 'Tell me about yourself.', duration: 240, score: 150 },
      { type: 'nonTechnical', text: `What is one of your hobbies, like ${resume.hobbies[0]}?`, duration: 360, score: 100 },
      { type: 'nonTechnical', text: 'Why should we hire you?', duration: 0, score: 100 },
      { type: 'technical', text: `How did you use ${resume.skills[0]} in your project?`, duration: 900, score: 50 },
      { type: 'technical', text: 'What is semantic HTML? Give examples.', duration: 0, score: 50 },
      { type: 'technical', text: 'Explain the CSS Box Model.', duration: 0, score: 50 },
      { type: 'technical', text: `Describe your approach to ${resume.projects[0]}.`, duration: 0, score: 50 },
      { type: 'technical', text: 'What is the difference between let, var, and const?', duration: 0, score: 50 },
    ],
    DataScience: [
      { type: 'introduction', text: 'Tell me about yourself.', duration: 240, score: 150 },
      { type: 'nonTechnical', text: `What is one of your strengths, like ${resume.hobbies[0]}?`, duration: 360, score: 100 },
      { type: 'nonTechnical', text: 'Why are you interested in Data Science?', duration: 0, score: 100 },
      { type: 'technical', text: `How did you use ${resume.skills[0]} in a project?`, duration: 900, score: 50 },
      { type: 'technical', text: 'What is Pandas and how is it used?', duration: 0, score: 50 },
      { type: 'technical', text: 'Explain the difference between supervised and unsupervised learning.', duration: 0, score: 50 },
      { type: 'technical', text: `Describe your approach to ${resume.projects[0]}.`, duration: 0, score: 50 },
      { type: 'technical', text: 'What is the time complexity of a linear search?', duration: 0, score: 50 },
    ],
    // Add other tracks (Backend, MERN, etc.) similarly
  };

  const questions = questionBanks[selectedTech] || questionBanks.Frontend;

  // Avatar sequence
  useEffect(() => {
    if (avatarState === 'observing') {
      setTimeout(() => {
        setAvatarState('greeting');
        setAvatarMessage(`Welcome, ${userName}! This is your first step to fulfilling your dream in the ${selectedTech} field. Ready to start the interview?`);
        setAvatarExpression('happy');
        setRightContent(
          <div className="text-center">
            <h2 className="text-3xl font-bold text-white">Welcome to M   ockInterview</h2>
            <button
              onClick={() => setAvatarState('questioning')}
              className="mt-4 bg-green-600 text-white px-4 py-2 rounded hover:bg-green-700"
              aria-label="Start interview"
            >
              Yes
            </button>
          </div>
        );
      }, 4000);
    }
  }, [avatarState, userName, selectedTech]);

  // Recording consent
  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: true, audio: true });
      mediaRecorderRef.current = new MediaRecorder(stream);
      mediaRecorderRef.current.ondataavailable = (e) => recordedChunks.current.push(e.data);
      mediaRecorderRef.current.start();
      setIsRecording(true);
      setShowConsentModal(false);
    } catch (err) {
      console.error('Recording failed:', err);
      setShowConsentModal(false);
    }
  };

  // Question and timer logic
  useEffect(() => {
    if (avatarState !== 'questioning' || currentQuestionIndex >= questions.length) return;

    const currentQuestion = questions[currentQuestionIndex];
    setRightContent(
      <div className="text-center">
        <h2 className="text-2xl font-bold text-white">{currentQuestion.text}</h2>
        <p className="text-green-500" aria-live="polite">
          Time remaining: {Math.floor(timer / 60)}:{(timer % 60).toString().padStart(2, '0')}
        </p>
        {warnings.length > 0 && (
          <p className="text-red-500" aria-live="assertive">
            Warning: {warnings[warnings.length - 1]}
          </p>
        )}
        {currentQuestion.type === 'technical' && selectedTech === 'Frontend' && (
          <textarea
            className="w-full h-40 p-2 mt-4 bg-gray-800 text-white rounded"
            placeholder="Write your code here..."
            aria-label="Code input for technical question"
          />
        )}
      </div>
    );
    setAvatarMessage(currentQuestion.text);
    setAvatarExpression('thinking');

    timerRef.current = setInterval(() => {
      setTimer((prev) => {
        if (prev <= 0) {
          clearInterval(timerRef.current);
          if (currentQuestionIndex === 0 && prev > -30) {
            return prev - 1; // 30-second grace period
          }
          // Mock follow-up question if time remains
          if (prev >= 60 && currentQuestionIndex < questions.length - 1) {
            setAvatarMessage(`Follow-up: Can you elaborate on your answer?`);
            setRightContent(
              <div>
                <h2 className="text-2xl font-bold text-white">Follow-up: Can you elaborate on your answer?</h2>
                <p className="text-green-500" aria-live="polite">
                  Time remaining: {Math.floor(prev / 60)}:{(prev % 60).toString().padStart(2, '0')}
                </p>
              </div>
            );
            return prev;
          }
          setCurrentQuestionIndex((i) => i + 1);
          return 0;
        }
        return prev - 1;
      });
    }, 1000);

    // Mock behavioral warnings
    const warningInterval = setInterval(() => {
      const behaviors = [
        'Your shirt is wrinkled. Please wear ironed attire.',
        'Hair appears messy. Ensure neat grooming.',
        'Greeting lacked a smile. Try a warm expression.',
        'Eye contact wavered. Look at the camera.',
        'Speech included fillers. Avoid "um" or "uh."',
        'Posture is closed. Use open gestures.',
        'Response lacked positivity. Stay enthusiastic.',
        'Vague skill explanation. Quantify your impact.',
      ];
      if (warnings.length < 8 && Math.random() < 0.2) {
        setWarnings((prev) => [...prev, behaviors[warnings.length]]);
        setAvatarExpression('sad');
        setAvatarMessage(behaviors[warnings.length]);
      }
    }, 5000);

    return () => {
      clearInterval(timerRef.current);
      clearInterval(warningInterval);
    };
  }, [avatarState, currentQuestionIndex, timer, selectedTech]);

  // Start questions
  useEffect(() => {
    if (avatarState === 'questioning' && currentQuestionIndex === -1) {
      setCurrentQuestionIndex(0);
      setTimer(questions[0].duration);
    }
  }, [avatarState, currentQuestionIndex, questions]);

  // End of interview
  useEffect(() => {
    if (currentQuestionIndex >= questions.length) {
      if (mediaRecorderRef.current) {
        mediaRecorderRef.current.stop();
      }
      // Mock scoring
      const resumeScore = Math.floor(Math.random() * 400);
      const introScore = Math.floor(Math.random() * 150);
      const nonTechScore = Math.floor(Math.random() * 200);
      const techScore = Math.floor(Math.random() * 250);
      setScores({
        resume: resumeScore,
        introduction: introScore,
        nonTechnical: nonTechScore,
        technical: techScore,
      });

      // Track-specific micro-achievements
      const achievements = [];
      if (introScore >= 135) achievements.push(`${selectedTech} Greeting Pro`);
      if (introScore >= 120) achievements.push(`${selectedTech} First Impression Star`);
      if (nonTechScore >= 180) achievements.push(`${selectedTech} Storytelling Ace`);
      if (techScore >= 225) achievements.push(`${selectedTech} Tech Novice`);
      setMicroAchievements(achievements);

      navigate('/nexus-feedback', {
        state: {
          scores,
          warnings,
          microAchievements,
          recordedChunks: recordedChunks.current,
          track: selectedTech,
        },
      });
    }
  }, [currentQuestionIndex, navigate, selectedTech]);

  // Consent modal
  if (showConsentModal) {
    return (
      <div className="min-h-screen bg-charcoal text-white flex items-center justify-center">
        <div className="bg-gray-800 p-6 rounded-xl shadow-2xl max-w-md w-full">
          <h2 className="text-2xl font-semibold mb-4">Recording Consent</h2>
          <p className="text-gray-300 mb-4">
            We’d like to record your Nexus stage interview for {selectedTech} to provide Guided Video Replay feedback. The video stays in your browser’s local storage.
          </p>
          <p className="text-gray-300 mb-4">
            Agree to record?{' '}
            <a href="/privacy" className="text-blue-500">
              Learn More: How we protect your data
            </a>
          </p>
          <div className="flex justify-center gap-4">
            <button
              onClick={startRecording}
              className="bg-green-600 text-white px-4 py-2 rounded hover:bg-green-700"
            >
              Agree
            </button>
            <button
              onClick={() => setShowConsentModal(false)}
              className="bg-gray-600 text-white px-4 py-2 rounded hover:bg-gray-700"
            >
              Disagree
            </button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-charcoal text-white">
      <style>
        {`
          .bg-charcoal {
            background-color: #333333;
          }
          .professional-room {
            background-image: url('/images/professional-room.jpg');
            background-size: cover;
            background-position: center;
            height: 100%;
          }
          .spinner {
            animation: spin 1s linear infinite;
          }
          @keyframes spin {
            0% { transform: rotate(0deg); }
            100% { transform: rotate(360deg); }
          }
        `}
      </style>
      <NavBar />
      <SplitScreen
        avatarProps={{
          message: avatarMessage,
          expression: avatarExpression,
          gender: userGender === 'male' ? 'female' : 'male',
          className: 'professional-room',
        }}
        rightContent={rightContent}
        isLeftCollapsed={isLeftCollapsed}
        setIsLeftCollapsed={setIsLeftCollapsed}
        leftWidth={leftWidth}
        setLeftWidth={setLeftWidth}
      />
    </div>
  );
};

export default CodeEditorPage;