// /src/components/common/Avatar.jsx
import React, { useEffect } from 'react';
import { speak } from './TextToSpeech';

const Avatar = ({ text, expression = 'neutral', speechRate = 1.0 }) => {
  useEffect(() => {
    if (text) speak(text, speechRate);
  }, [text, speechRate]);

  return (
    <div className="flex flex-col items-center">
      <img src={`/avatars/${expression}.png`} alt="Avatar" className="w-32 h-32" />
      {text && <div className="mt-2 bg-white p-2 rounded shadow">{text}</div>}
    </div>
  );
};

export default Avatar;